import copy, re, difflib, zipfile
from lxml import etree
WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
W="{%s}"%WNS
XML_SPACE="{http://www.w3.org/XML/1998/namespace}space"
AUTHOR="Whitfield Corr & Loewe LLP"
DATE="2025-04-03T09:00:00Z"
_id=[5000]
def nid():
    _id[0]+=1; return str(_id[0])
def el(tag, **attrs):
    e=etree.Element(W+tag)
    for k,v in attrs.items(): e.set(W+k, v)
    return e
def ptext(p):
    return "".join(t.text or "" for t in p.iter(W+"t"))

def accept_all(body):
    root=body
    for d in list(root.iter(W+"del")):
        par=d.getparent()
        if par is not None: par.remove(d)
    for i in list(root.iter(W+"ins")):
        par=i.getparent()
        if par is None: continue
        if par.tag==W+"rPr":  # paragraph mark / run mark
            par.remove(i); continue
        idx=par.index(i)
        for c in list(i): par.insert(idx,c); idx+=1
        par.remove(i)
    for tag in ("rPrChange","pPrChange","trPrChange","tblPrChange"):
        for x in list(root.iter(W+tag)): x.getparent().remove(x)

def clean_rpr(rpr):
    r=copy.deepcopy(rpr) if rpr is not None else el("rPr")
    for x in r.findall(W+"ins")+r.findall(W+"del"): r.remove(x)
    return r

def para_chars(p):
    """list of (char, rPr_xmlstring) for simple text runs"""
    out=[]
    for r in p.findall(W+"r"):
        rpr=r.find(W+"rPr")
        rs=etree.tostring(clean_rpr(rpr)).decode()
        for t in r:
            if t.tag==W+"t":
                for ch in (t.text or ""): out.append((ch,rs))
            elif t.tag==W+"tab":
                out.append(("\t",rs))
    return out

def base_rpr(p):
    best=None
    for r in p.findall(W+"r"):
        rpr=r.find(W+"rPr")
        if rpr is None or not ptext(r): continue
        if rpr.find(W+"b") is None: return clean_rpr(rpr)
        if best is None: best=rpr
    r=clean_rpr(best)
    for x in r.findall(W+"b"): r.remove(x)
    return r

def make_rpr(base, bold=False, italic=False, underline=False):
    r=copy.deepcopy(base)
    for t in ("b","i","u"):
        for x in r.findall(W+t): r.remove(x)
    # order: rFonts, b, i, ..., color, sz, u
    pos=1 if r.find(W+"rFonts") is not None else 0
    if italic: r.insert(pos, el("i"))
    if bold: r.insert(pos, el("b"))
    if underline: r.append(el("u", val="single"))
    return etree.tostring(r).decode()

def parse_markup(text, base):
    """**bold**, __italic__ ; returns list of (char, rprstring)"""
    out=[]
    parts=re.split(r"(\*\*|__)", text)
    b=False;i=False
    for part in parts:
        if part=="**": b=not b; continue
        if part=="__": i=not i; continue
        rs=make_rpr(base,b,i)
        for ch in part: out.append((ch,rs))
    return out

def mk_run(text, rs, deleted=False):
    r=el("r"); r.append(etree.fromstring(rs))
    t=el("delText" if deleted else "t"); t.text=text; t.set(XML_SPACE,"preserve")
    r.append(t); return r

def group(chars):
    res=[]
    for ch,rs in chars:
        if res and res[-1][1]==rs: res[-1][0]+=ch
        else: res.append([ch,rs])
    return res

def tok(s):
    return re.findall(r"\s+|[A-Za-z0-9]+|[^A-Za-z0-9\s]", s)

def revise(p, newtext):
    """word-level tracked diff of paragraph p against new text (markup)"""
    old=para_chars(p)
    base=base_rpr(p)
    new=parse_markup(newtext, base)
    ot="".join(c for c,_ in old); nt="".join(c for c,_ in new)
    otok=tok(ot); ntok=tok(nt)
    # char offsets
    def offs(toks):
        o=[0]
        for t in toks: o.append(o[-1]+len(t))
        return o
    oo=offs(otok); no=offs(ntok)
    sm=difflib.SequenceMatcher(None, otok, ntok, autojunk=False)
    items=[]
    for op,i1,i2,j1,j2 in sm.get_opcodes():
        if op=="equal":
            items.append(("eq", old[oo[i1]:oo[i2]]))
        else:
            if i2>i1: items.append(("del", old[oo[i1]:oo[i2]]))
            if j2>j1: items.append(("ins", new[no[j1]:no[j2]]))
    # remove all runs, keep pPr and others (bookmarks etc.)
    for r in p.findall(W+"r"): p.remove(r)
    for kind,chars in items:
        for txt,rs in group(chars):
            if kind=="eq": p.append(mk_run(txt,rs))
            elif kind=="del":
                d=el("del", id=nid(), author=AUTHOR, date=DATE); d.append(mk_run(txt,rs,True)); p.append(d)
            else:
                a=el("ins", id=nid(), author=AUTHOR, date=DATE); a.append(mk_run(txt,rs)); p.append(a)
    return p

def mark_ppr(ppr, kind):
    rpr=ppr.find(W+"rPr")
    if rpr is None:
        rpr=el("rPr"); ppr.append(rpr)
    rpr.insert(0, el(kind, id=nid(), author=AUTHOR, date=DATE))

def new_para(template_p, text, base=None, center=None, pagebreak=False):
    p=el("p")
    tp=template_p.find(W+"pPr")
    ppr=copy.deepcopy(tp) if tp is not None else el("pPr")
    for x in ppr.findall(W+"rPr"): ppr.remove(x)
    if center is not None:
        for x in ppr.findall(W+"jc"): ppr.remove(x)
        ppr.append(el("jc", val=center))
    if pagebreak:
        ppr.insert(0, el("pageBreakBefore"))
    p.append(ppr)
    mark_ppr(ppr,"ins")
    if base is None: base=base_rpr(template_p)
    a=el("ins", id=nid(), author=AUTHOR, date=DATE)
    for txt,rs in group(parse_markup(text, base)):
        a.append(mk_run(txt,rs))
    p.append(a)
    return p

def delete_para(p):
    ppr=p.find(W+"pPr")
    if ppr is None:
        ppr=el("pPr"); p.insert(0,ppr)
    mark_ppr(ppr,"del")
    for r in p.findall(W+"r"):
        if not ptext(r):
            continue
        idx=p.index(r)
        for t in r.findall(W+"t"): t.tag=W+"delText"
        d=el("del", id=nid(), author=AUTHOR, date=DATE)
        p.remove(r); d.append(r); p.insert(idx,d)

def insert_after(anchor, newels):
    par=anchor.getparent(); idx=par.index(anchor)
    for e in newels:
        idx+=1; par.insert(idx,e)
    return newels[-1] if newels else anchor

def insert_before(anchor, newels):
    par=anchor.getparent(); idx=par.index(anchor)
    for e in newels:
        par.insert(idx,e); idx+=1

# ---------- comments ----------
COMMENTS=[]
def comment(p, text, author="J. Okafor (WCL)", initials="JO", start_el=None, end_el=None):
    cid=str(len(COMMENTS))
    COMMENTS.append((cid,author,initials,text))
    cs=el("commentRangeStart", id=cid); ce=el("commentRangeEnd", id=cid)
    sp=start_el if start_el is not None else p
    ep=end_el if end_el is not None else p
    ppr=sp.find(W+"pPr")
    sp.insert(sp.index(ppr)+1 if ppr is not None else 0, cs)
    ep.append(ce)
    r=el("r"); rpr=el("rPr"); rpr.append(el("rStyle", val="CommentReference")); r.append(rpr)
    r.append(el("commentReference", id=cid)); ep.append(r)

def comments_xml():
    root=etree.Element(W+"comments", nsmap={"w":WNS})
    for cid,author,ini,text in COMMENTS:
        c=el("comment", id=cid, author=author, date=DATE, initials=ini)
        for para in text.split("\n"):
            p=el("p"); r=el("r"); rpr=el("rPr")
            rpr.append(el("sz", val="18")); r.append(rpr)
            t=el("t"); t.text=para; t.set(XML_SPACE,"preserve"); r.append(t); p.append(r); c.append(p)
        root.append(c)
    return etree.tostring(root, xml_declaration=True, encoding="UTF-8", standalone=True)

# ---------- tables ----------
def new_table(headers, nrows, widths, font_sz="16", label_first=True):
    tbl=el("tbl")
    tp=el("tblPr"); tp.append(el("tblW", type="dxa", w=str(sum(widths)))); tp.append(el("jc", val="center"))
    b=el("tblBorders")
    for s in ("top","left","bottom","right","insideH","insideV"):
        b.append(el(s, val="single", sz="4", space="0", color="000000"))
    tp.append(b); tp.append(el("tblLayout", type="fixed")); tbl.append(tp)
    g=el("tblGrid")
    for w in widths: g.append(el("gridCol", w=str(w)))
    tbl.append(g)
    def row(vals, bold):
        tr=el("tr"); trp=el("trPr"); trp.append(el("ins", id=nid(), author=AUTHOR, date=DATE))
        if bold: trp.append(el("tblHeader"))
        tr.append(trp)
        for v,w in zip(vals,widths):
            tc=el("tc"); tcp=el("tcPr"); tcp.append(el("tcW", type="dxa", w=str(w)))
            if bold: tcp.append(el("shd", val="clear", color="auto", fill="D9D9D9"))
            tc.append(tcp)
            p=el("p"); ppr=el("pPr"); ppr.append(el("spacing", before="20", after="20", line="240", lineRule="auto"))
            p.append(ppr); mark_ppr(ppr,"ins")
            base=etree.fromstring(f"<w:rPr xmlns:w=\"{WNS}\"><w:rFonts w:ascii=\"Times New Roman\" w:hAnsi=\"Times New Roman\"/><w:color w:val=\"000000\"/><w:sz w:val=\"{font_sz}\"/></w:rPr>")
            if v:
                a=el("ins", id=nid(), author=AUTHOR, date=DATE)
                a.append(mk_run(v, make_rpr(base,bold))); p.append(a)
            tc.append(p); tr.append(tc)
        return tr
    tbl.append(row(headers, True))
    for i in range(nrows):
        tbl.append(row([str(i+1)]+[""]*(len(headers)-1), False))
    return tbl
